INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 102301, 0.0, 0.0, "アヤネ", 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, "2020/07/31 12:00:00", 24, 0.0, 24001, "2030/12/17 14:59:59", 401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 102301, 0.0, 0.0, "アヤネ", 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 1, "2020/07/31 12:00:00", 24, 2.21, 24002, "2030/12/17 14:59:59", 402);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 102301, 0.0, 0.0, "アヤネ", 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, "2020/07/31 12:00:00", 24, 0.0, 24003, "2030/12/17 14:59:59", 403);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192201, 0.0, 0.0, "アサヒ", 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 2, "2020/07/31 12:00:00", 24, 1.99, 24004, "2030/12/17 14:59:59", 701);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192201, 0.0, 0.0, "アサヒ", 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 1, "2020/07/31 12:00:00", 24, 2.21, 24005, "2030/12/17 14:59:59", 702);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192201, 0.0, 0.0, "アサヒ", 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 2, "2020/07/31 12:00:00", 24, 3.33, 24006, "2030/12/17 14:59:59", 703);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192301, 0.0, 0.0, "部員３", 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, "2020/07/31 12:00:00", 24, 0.0, 24007, "2030/12/17 14:59:59", 801);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192301, 0.0, 0.0, "部員３", 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 1, "2020/07/31 12:00:00", 24, 2.68, 24008, "2030/12/17 14:59:59", 802);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192301, 0.0, 0.0, "部員３", 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, "2020/07/31 12:00:00", 24, 0.0, 24009, "2030/12/17 14:59:59", 803);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192501, 0.0, 0.0, "", 1, "やった！", 1, "2020/07/31 12:00:00", 24, 0.0, 24010, "2030/12/17 14:59:59", 501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192501, 0.0, 0.0, "", 1, "勝ったよ！", 1, "2020/07/31 12:00:00", 24, 0.0, 24011, "2030/12/17 14:59:59", 502);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192501, 0.0, 0.0, "", 1, "いい調子！", 1, "2020/07/31 12:00:00", 24, 0.0, 24012, "2030/12/17 14:59:59", 503);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, 0.0, 0.0, "ミサト", 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 6, "2020/07/31 12:00:00", 24, 5.33, 24013, "2030/12/17 14:59:59", 111);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, 0.0, 0.0, "ミサト", 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 1, "2020/07/31 12:00:00", 24, 6.85, 24014, "2030/12/17 14:59:59", 112);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, 0.0, 0.0, "ミサト", 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 1, "2020/07/31 12:00:00", 24, 3.0, 24015, "2030/12/17 14:59:59", 113);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192401, 0.0, 0.0, "ダイチ", 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 1, "2020/07/31 12:00:00", 24, 6.11, 24016, "2030/12/17 14:59:59", 611);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192401, 0.0, 0.0, "ダイチ", 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 1, "2020/07/31 12:00:00", 24, 6.75, 24017, "2030/12/17 14:59:59", 612);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192401, 0.0, 0.0, "ダイチ", 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, "2020/07/31 12:00:00", 24, 0.0, 24018, "2030/12/17 14:59:59", 613);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113401, 0.0, 0.0, "ハツネ", 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 2, "2020/07/31 12:00:00", 24, 4.52, 24019, "2030/12/17 14:59:59", 211);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113401, 0.0, 0.0, "ハツネ", 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 2, "2020/07/31 12:00:00", 24, 3.89, 24020, "2030/12/17 14:59:59", 212);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113401, 0.0, 0.0, "ハツネ", 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 1, "2020/07/31 12:00:00", 24, 13.49, 24021, "2030/12/17 14:59:59", 213);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 106501, 0.0, 0.0, "カヤ", 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 1, "2020/07/31 12:00:00", 24, 3.17, 24022, "2030/12/17 14:59:59", 311);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 106501, 0.0, 0.0, "カヤ", 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 1, "2020/07/31 12:00:00", 24, 4.42, 24023, "2030/12/17 14:59:59", 312);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 106501, 0.0, 0.0, "カヤ", 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 6, "2020/07/31 12:00:00", 24, 2.89, 24024, "2030/12/17 14:59:59", 313);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 102301, 0.0, 0.0, "アヤネ", 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 4, "2020/07/31 12:00:00", 24, 3.71, 24025, "2030/12/17 14:59:59", 421);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192201, 0.0, 0.0, "アサヒ", 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 2, "2020/07/31 12:00:00", 24, 5.1, 24026, "2030/12/17 14:59:59", 721);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192301, 0.0, 0.0, "部員３", 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 1, "2020/07/31 12:00:00", 24, 4.34, 24027, "2030/12/17 14:59:59", 821);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 192501, 0.0, 0.0, "", 1, "いい勝負だったよ\nまたやろうね", 1, "2020/07/31 12:00:00", 24, 0.0, 24028, "2030/12/17 14:59:59", 521);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, -360.0, 0.0, "ミサト", 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 1, "2020/07/31 12:00:00", 24, 5.62, 24029, "2030/12/17 14:59:59", 101);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, -360.0, 0.0, "ミサト", 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 1, "2020/07/31 12:00:00", 24, 9.58, 24030, "2030/12/17 14:59:59", 102);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, -360.0, 0.0, "ミサト", 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, "2020/07/31 12:00:00", 24, 0.0, 24031, "2030/12/17 14:59:59", 103);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, -360.0, 0.0, "ミサト", 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 2, "2020/07/31 12:00:00", 24, 9.13, 24032, "2030/12/17 14:59:59", 104);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES (10046, 113501, -360.0, 0.0, "ミサト", 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 1, "2020/07/31 12:00:00", 24, 8.27, 24033, "2030/12/17 14:59:59", 105);
